                <div
                    className="fixed inset-0 bg-black/50 z-40"
                    onClick={() => {
                        setIsMenuOpen(false);
                        playClick(sfxPlayer.current);
                    }}
                />
            )}
            <MenuDrawer isOpen={isMenuOpen} skills={skills} stats={stats} />

            {/* Bottom Right Bug Report Button */}
