                                        >
                                            {config.challengeType === 'writing' ? (
                                                // Display single or multiple item images for writing challenge
                                                <div className="flex items-center justify-center gap-2">
                                                    {challenge?.images?.map((img, idx) => (
                                                        <React.Fragment key={idx}>
