                                            <div className="relative w-full flex justify-center">
                                                <input
                                                    ref={inputRef}
                                                    type="text"
                                                    value={mathInput}
                                                    onChange={(e) => {
                                                        const val = e.target.value
                                                            .toUpperCase()
                                                            .replace(/\s/g, '');
                                                        setMathInput(val);
                                                        const answerNoSpaces =
                                                            challenge?.answer.replace(/\s/g, '');
                                                        if (val === answerNoSpaces) {
                                                            onMathSubmit(val);
                                                            setMathInput('');
                                                        } else if (
                                                            val.length === answerNoSpaces.length
                                                        ) {
                                                            setIsWrong(true);
                                                            playMismatch();
                                                            setTimeout(() => {
                                                                setIsWrong(false);
                                                                setMathInput('');
                                                                setTimeout(
                                                                    () => inputRef.current?.focus(),
                                                                    10,
